import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type StadiumDotsProps = Record<string, any>;

const StadiumDots: React.FC<StadiumDotsProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 8,
  dotColor = "#800080", // Purple
  textColor = "#87102d", // Requested Red
  
  // Left Side Defaults
  rows = 5,
  columns = 10,
  mainText = "Stadium of 50,000\nrandom people", 
  
  // Right Side Defaults
  rightRows = 1,
  rightColumns = 5,
  rightText = "50 exact ideal customers",

  dotSize = 30,
  gap = 15,
  sectionsGap = 300,
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- TIMING CONFIGURATION ---
  const rightStartDelay = 45; // Frames before right side starts
  const waitDuration = fps * 2; // 2 seconds wait
  const fadeStartFrame = rightStartDelay + 30 + waitDuration; // When left side starts fading

  // --- RENDER HELPER ---
  const renderGroup = (
    rRows: number, 
    rCols: number, 
    text: string, 
    startFrame: number, 
    shouldFadeOut: boolean
  ) => {
    const totalDots = rRows * rCols;
    
    // Opacity Logic
    let groupOpacity = 1;
    if (shouldFadeOut) {
      groupOpacity = interpolate(
        frame,
        [fadeStartFrame, fadeStartFrame + 15],
        [1, 0],
        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
      );
    }

    // Text Animation
    const textOpacity = spring({
      frame: frame - startFrame - 10,
      fps,
      config: { damping: 12 },
    });
    const textSlide = interpolate(
      textOpacity,
      [0, 1],
      [20, 0],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );

    // Dot Animation (All appear same time)
    const dotScale = spring({
      frame: frame - startFrame,
      fps,
      config: {
        damping: 15,
        stiffness: 120,
        mass: 0.5,
      },
    });

    return (
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 40,
          opacity: groupOpacity,
          width: width * 0.35, // Fixed width for columns
          alignItems: "center", // Center items in the column
        }}
      >
        {/* Grid Container */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: `repeat(${rCols}, ${dotSize}px)`,
            gridTemplateRows: `repeat(${rRows}, ${dotSize}px)`,
            gap: gap,
            justifyContent: "center",
          }}
        >
          {Array.from({ length: totalDots }).map((_, i) => (
            <div
              key={i}
              style={{
                width: dotSize,
                height: dotSize,
                borderRadius: "50%",
                backgroundColor: dotColor,
                transform: `scale(${dotScale})`,
                opacity: dotScale,
                boxShadow: `0 0 15px ${dotColor}, 0 0 30px ${dotColor}`, // Increased Glow
              }}
            />
          ))}
        </div>

        {/* Text Container */}
        <div
          style={{
            opacity: textOpacity,
            transform: `translateY(${textSlide}px)`,
            color: textColor,
            fontSize: 42,
            fontWeight: 700,
            textAlign: "center",
            whiteSpace: "pre-wrap", // Handle newlines
            lineHeight: 1.2,
            textShadow: `0 0 20px ${textColor}, 0 0 40px ${textColor}`, // Increased Glow
          }}
        >
          {text}
        </div>
      </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Montserrat",
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* Wrapper to align items to the bottom (text alignment) */}
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "flex-end", // Aligns the text blocks horizontally
          gap: sectionsGap,
        }}
      >
        {/* LEFT SIDE: Stadium */}
        {renderGroup(rows, columns, mainText, 0, true)}

        {/* RIGHT SIDE: Ideal Customers */}
        {renderGroup(rightRows, rightColumns, rightText, rightStartDelay, false)}
      </div>
    </AbsoluteFill>
  );
};

export default StadiumDots;